    {
      "tag": "MOAT-CHECK",
      "domain": "BIZ",
      "body": "Never claim \"data moat\" without specifying: what data, how collected, why competitors can't replicate within 6 months."
    },
    {
      "tag": "COMPETITOR-DEEP",
      "domain": "BIZ",
      "body": "Never claim \"no one does X\" without searching ProductHunt, G2, Capterra, and GitHub for alternatives."
    },
    {
      "tag": "PRICING-REALITY",
      "domain": "BIZ",
      "body": "Never set price without evidence of actual willingness-to-pay from forums, competitor pricing pages, or survey data."
